window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d84cc1eca92e394c"]={"versions": [{"id": "FIG-d84cc1eca92e394c", "releases": ["R19-03"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong> Definiert die formale Modellierung der Instanziierung des Functional Clusters <strong>UCM</strong> (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Es verankert UCM im allgemeinen Instanziierungsbaum der Adaptive-Plattform-Module und ermöglicht die eindeutige Adressierung spezifischer UCM-Instanzen im Fahrzeugnetzwerk (gemäß <code>RS_MANI_00023</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Identifiable</code></strong> <em>(abstrakt / Core-Metaklasse)</em>:</li>\n<li>Oberste Abstraktion für alle referenzierbaren AUTOSAR-Modellelemente.</li>\n<li>Stellt Standardattribute bereit: <code>shortName</code> (Kardinalität [1], zwingend zur Pfadbildung), optionale UUIDs und Dokumentationsmetadaten.</li>\n<li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>Identifiable</code>)</em>:</li>\n<li>Abstrakte Basisklasse für die Konfiguration und Bereitstellung von Adaptive-Plattform-Basisdiensten bzw. Functional Clusters auf einer konkreten Ziel-Maschine (<code>Machine</code>).</li>\n<li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, erbt via Generalisierung von <code>AdaptiveModuleInstantiation</code>)</em>:</li>\n<li>Differenziert Modulinstanzen, die keine direkten Betriebssystem-Prozesskonfigurationen (<code>OsModuleInstantiation</code> / Prozess-Scheduling) kapseln, sondern stack-interne Dienste und Functional-Cluster-Ressourcen parametrisieren.</li>\n<li><strong><code>UcmModuleInstantiation</code></strong> <em>(konkret, erbt via Generalisierung von <code>NonOsModuleInstantiation</code>)</em>:</li>\n<li>Spezifische Manifest-Entität zur Repräsentation einer UCM-Instanz auf der jeweiligen Adaptive Platform Machine.</li>\n<li><strong>Attribut:</strong></li>\n<li><code>+ identifier: PositiveInteger</code> (Kardinalität [1]): Eindeutige, ganzzahlige Kennung der UCM-Instanz (<code>TPS_MANI_01226</code>, <code>TPS_MANI_01227</code>).</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf (falls zutreffend)</h4>\n<ul class=\"fig-list\">\n<li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen prozeduralen Ablauf ab.</li>\n<li><strong>Laufzeit-Bezug:</strong></li>\n<li>Der statisch konfigurierte <code>identifier</code> dient zur Laufzeit dem Routing und Dispatching von Aktualisierungspaketen.</li>\n<li>In heterogenen Multi-UCM-Architekturen (z. B. zentraler <em>Vehicle Update Manager</em> steuert mehrere lokale <em>Target-UCMs</em>) prüft der UCM-Daemon bei eingehenden Software-Paketen, ob das Paket für seinen konfigurierten <code>identifier</code> bestimmt ist, bevor die Update-Zustandsmaschine (Transferring, Processing, Activating) initiiert wird.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Erstellung & XML-Schema:</strong></li>\n<li>Im ARXML des <em>Machine Manifests</em> ist pro UCM-Dienstinstanz ein <code>&lt;UCM-MODULE-INSTANTIATION&gt;</code> unterhalb der jeweiligen <code>&lt;MACHINE&gt;</code> anzulegen.</li>\n<li>Der Pfad erfordert einen gültigen <code>&lt;SHORT-NAME&gt;</code> (geerbt von <code>Identifiable</code>) und zwingend das Element <code>&lt;IDENTIFIER&gt;</code> mit einem ganzzahligen Wert $> 0$.</li>\n<li><strong>Stack- & Integrator-Relevanz:</strong></li>\n<li><strong>Generatoren / Backend:</strong> Manifest-Generatoren mappen <code>identifier</code> direkt in Konfigurations-Header, Initialisierungs-Payloads oder IPC/ara::com-Dienstinstanz-IDs des UCM-Daemons.</li>\n<li><strong>Eindeutigkeit & Flottenarchitektur:</strong> Der <code>identifier</code> muss im Adressbereich des Gesamtfahrzeug-Update-Managers eindeutig vergeben werden, um Fehlzustellungen von Software-Bundles und Rollbacks bei OTA-Kampagnen deterministisch zu verhindern.</li>\n</ul>"}, {"id": "FIG-f5e1a0b0f072564c", "releases": ["R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong> Definiert die formale Modellierung der Instanziierung des Functional Clusters <strong>UCM</strong> (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Es verankert UCM im allgemeinen Instanziierungsbaum der Adaptive-Plattform-Module und ermöglicht die eindeutige Adressierung spezifischer UCM-Instanzen im Fahrzeugnetzwerk (gemäß <code>RS_MANI_00023</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Identifiable</code></strong> <em>(abstrakt / Core-Metaklasse)</em>:</li>\n<li>Oberste Abstraktion für alle referenzierbaren AUTOSAR-Modellelemente.</li>\n<li>Stellt Standardattribute bereit: <code>shortName</code> (Kardinalität [1], zwingend zur Pfadbildung), optionale UUIDs und Dokumentationsmetadaten.</li>\n<li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>Identifiable</code>)</em>:</li>\n<li>Abstrakte Basisklasse für die Konfiguration und Bereitstellung von Adaptive-Plattform-Basisdiensten bzw. Functional Clusters auf einer konkreten Ziel-Maschine (<code>Machine</code>).</li>\n<li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, erbt via Generalisierung von <code>AdaptiveModuleInstantiation</code>)</em>:</li>\n<li>Differenziert Modulinstanzen, die keine direkten Betriebssystem-Prozesskonfigurationen (<code>OsModuleInstantiation</code> / Prozess-Scheduling) kapseln, sondern stack-interne Dienste und Functional-Cluster-Ressourcen parametrisieren.</li>\n<li><strong><code>UcmModuleInstantiation</code></strong> <em>(konkret, erbt via Generalisierung von <code>NonOsModuleInstantiation</code>)</em>:</li>\n<li>Spezifische Manifest-Entität zur Repräsentation einer UCM-Instanz auf der jeweiligen Adaptive Platform Machine.</li>\n<li><strong>Attribut:</strong></li>\n<li><code>+ identifier: String</code> (Kardinalität [1]): Eindeutige Kennung der UCM-Instanz als Zeichenkette.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen prozeduralen Ablauf ab.</li>\n<li><strong>Laufzeit-Bezug:</strong></li>\n<li>Der statisch konfigurierte <code>identifier</code> dient zur Laufzeit dem Routing und Dispatching von Aktualisierungspaketen.</li>\n<li>In heterogenen Multi-UCM-Architekturen (z. B. zentraler <em>Vehicle Update Manager</em> steuert mehrere lokale <em>Target-UCMs</em>) prüft der UCM-Daemon bei eingehenden Software-Paketen, ob das Paket für seinen konfigurierten <code>identifier</code> bestimmt ist, bevor die Update-Zustandsmaschine (Transferring, Processing, Activating) initiiert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Erstellung & XML-Schema:</strong></li>\n<li>Im ARXML des <em>Machine Manifests</em> ist pro UCM-Dienstinstanz ein <code>&lt;UCM-MODULE-INSTANTIATION&gt;</code> unterhalb der jeweiligen <code>&lt;MACHINE&gt;</code> anzulegen.</li>\n<li>Der Pfad erfordert einen gültigen <code>&lt;SHORT-NAME&gt;</code> (geerbt von <code>Identifiable</code>) und zwingend das Element <code>&lt;IDENTIFIER&gt;</code> als String.</li>\n<li><strong>Stack- & Integrator-Relevanz:</strong></li>\n<li><strong>Generatoren / Backend:</strong> Manifest-Generatoren mappen <code>identifier</code> direkt in Konfigurations-Header, Initialisierungs-Payloads oder IPC/ara::com-Dienstinstanz-IDs des UCM-Daemons.</li>\n<li><strong>Eindeutigkeit & Flottenarchitektur:</strong> Der <code>identifier</code> muss im Adressbereich des Gesamtfahrzeug-Update-Managers eindeutig vergeben werden, um Fehlzustellungen von Software-Bundles und Rollbacks bei OTA-Kampagnen deterministisch zu verhindern.</li>\n</ul>"}, {"id": "FIG-d1e4d1f49b74913e", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong> Definiert die formale Modellierung der Instanziierung des Functional Clusters <strong>UCM</strong> (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Es verankert UCM im allgemeinen Instanziierungsbaum der Adaptive-Plattform-Module und ermöglicht die eindeutige Adressierung spezifischer UCM-Instanzen im Fahrzeugnetzwerk (gemäß <code>RS_MANI_00023</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Identifiable</code></strong> <em>(abstrakt / Core-Metaklasse)</em>:</li>\n<li>Oberste Abstraktion für alle referenzierbaren AUTOSAR-Modellelemente.</li>\n<li>Stellt Standardattribute bereit: <code>shortName</code> (Kardinalität [1], zwingend zur Pfadbildung), optionale UUIDs und Dokumentationsmetadaten.</li>\n<li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>Identifiable</code>)</em>:</li>\n<li>Abstrakte Basisklasse für die Konfiguration und Bereitstellung von Adaptive-Plattform-Basisdiensten bzw. Functional Clusters auf einer konkreten Ziel-Maschine (<code>Machine</code>).</li>\n<li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, erbt via Generalisierung von <code>AdaptiveModuleInstantiation</code>)</em>:</li>\n<li>Differenziert Modulinstanzen, die keine direkten Betriebssystem-Prozesskonfigurationen (<code>OsModuleInstantiation</code> / Prozess-Scheduling) kapseln, sondern stack-interne Dienste und Functional-Cluster-Ressourcen parametrisieren.</li>\n<li><strong><code>UcmModuleInstantiation</code></strong> <em>(konkret, erbt via Generalisierung von <code>NonOsModuleInstantiation</code>)</em>:</li>\n<li>Spezifische Manifest-Entität zur Repräsentation einer UCM-Instanz auf der jeweiligen Adaptive Platform Machine.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ identifier: String</code> (Kardinalität [1]): Eindeutige Kennung der UCM-Instanz als Zeichenkette.</li>\n<li><code>+ maxNumberOfParallelTransfers: PositiveInteger [0..1]</code>: Optionale Obergrenze für die Anzahl parallel unterstützter Datentransfers (Software-Pakete) zur UCM-Instanz.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen prozeduralen Ablauf ab.</li>\n<li><strong>Laufzeit-Bezug:</strong></li>\n<li>Der statisch konfigurierte <code>identifier</code> dient zur Laufzeit dem Routing und Dispatching von Aktualisierungspaketen.</li>\n<li>In heterogenen Multi-UCM-Architekturen (z. B. zentraler <em>Vehicle Update Manager</em> steuert mehrere lokale <em>Target-UCMs</em>) prüft der UCM-Daemon bei eingehenden Software-Paketen, ob das Paket für seinen konfigurierten <code>identifier</code> bestimmt ist, bevor die Update-Zustandsmaschine (Transferring, Processing, Activating) initiiert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Erstellung & XML-Schema:</strong></li>\n<li>Im ARXML des <em>Machine Manifests</em> ist pro UCM-Dienstinstanz ein <code>&lt;UCM-MODULE-INSTANTIATION&gt;</code> unterhalb der jeweiligen <code>&lt;MACHINE&gt;</code> anzulegen.</li>\n<li>Neben <code>&lt;SHORT-NAME&gt;</code> und dem Pflichtelement <code>&lt;IDENTIFIER&gt;</code> kann optional <code>&lt;MAX-NUMBER-OF-PARALLEL-TRANSFERS&gt;</code> als ganzzahliger Wert konfiguriert werden.</li>\n<li><strong>Stack- & Integrator-Relevanz:</strong></li>\n<li><strong>Ressourcenmanagement:</strong> <code>maxNumberOfParallelTransfers</code> dimensioniert die Puffer- und Thread-Ressourcen des UCM-Daemons für gleichzeitige Datenübertragungen. Fehlt die Angabe, greift das plattformspezifische Standardlimit.</li>\n<li><strong>Eindeutigkeit & Flottenarchitektur:</strong> Der <code>identifier</code> gewährleistet das eindeutige Ziel-Routing im Gesamtfahrzeugverbund.</li>\n</ul>"}, {"id": "FIG-2b8832dbea56b0bb", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong> Definiert die formale Modellierung der Instanziierung des Functional Clusters <strong>UCM</strong> (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Es verankert UCM im allgemeinen Instanziierungsbaum der Adaptive-Plattform-Module und ermöglicht die eindeutige Adressierung spezifischer UCM-Instanzen im Fahrzeugnetzwerk (gemäß <code>RS_MANI_00023</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>Identifiable</code></strong> <em>(abstrakt / Core-Metaklasse)</em>:</li>\n<li>Oberste Abstraktion für alle referenzierbaren AUTOSAR-Modellelemente.</li>\n<li>Stellt Standardattribute bereit: <code>shortName</code> (Kardinalität [1], zwingend zur Pfadbildung), optionale UUIDs und Dokumentationsmetadaten.</li>\n<li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>Identifiable</code>)</em>:</li>\n<li>Abstrakte Basisklasse für die Konfiguration und Bereitstellung von Adaptive-Plattform-Basisdiensten bzw. Functional Clusters auf einer konkreten Ziel-Maschine (<code>Machine</code>).</li>\n<li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, erbt via Generalisierung von <code>AdaptiveModuleInstantiation</code>)</em>:</li>\n<li>Differenziert Modulinstanzen, die keine direkten Betriebssystem-Prozesskonfigurationen (<code>OsModuleInstantiation</code> / Prozess-Scheduling) kapseln, sondern stack-interne Dienste und Functional-Cluster-Ressourcen parametrisieren.</li>\n<li><strong><code>UcmModuleInstantiation</code></strong> <em>(konkret, erbt via Generalisierung von <code>NonOsModuleInstantiation</code>)</em>:</li>\n<li>Spezifische Manifest-Entität zur Repräsentation einer UCM-Instanz auf der jeweiligen Adaptive Platform Machine.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ identifier: String</code> (Kardinalität [1]): Eindeutige Kennung der UCM-Instanz als Zeichenkette.</li>\n<li><code>+ maxNumberOfParallelTransfers: PositiveInteger [0..1]</code>: Optionale Obergrenze für die Anzahl parallel unterstützter Datentransfers zur UCM-Instanz.</li>\n<li><code>+ ucmSoftwareVersion: StrongRevisionLabelString [0..1]</code>: Optionale Versionsbezeichnung der UCM-Software gemäß formaler AUTOSAR-Revisionssyntax.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen prozeduralen Ablauf ab.</li>\n<li><strong>Laufzeit-Bezug:</strong></li>\n<li>Der statisch konfigurierte <code>identifier</code> dient zur Laufzeit dem Routing und Dispatching von Aktualisierungspaketen.</li>\n<li>In heterogenen Multi-UCM-Architekturen (z. B. zentraler <em>Vehicle Update Manager</em> steuert mehrere lokale <em>Target-UCMs</em>) prüft der UCM-Daemon bei eingehenden Software-Paketen, ob das Paket für seinen konfigurierten <code>identifier</code> bestimmt ist, bevor die Update-Zustandsmaschine (Transferring, Processing, Activating) initiiert wird.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Erstellung & XML-Schema:</strong></li>\n<li>Im ARXML des <em>Machine Manifests</em> ist pro UCM-Dienstinstanz ein <code>&lt;UCM-MODULE-INSTANTIATION&gt;</code> unterhalb der jeweiligen <code>&lt;MACHINE&gt;</code> anzulegen.</li>\n<li>Neben <code>&lt;SHORT-NAME&gt;</code> und <code>&lt;IDENTIFIER&gt;</code> können optional <code>&lt;MAX-NUMBER-OF-PARALLEL-TRANSFERS&gt;</code> sowie <code>&lt;UCM-SOFTWARE-VERSION&gt;</code> deklariert werden.</li>\n<li><strong>Stack- & Integrator-Relevanz:</strong></li>\n<li><strong>Software-Inventarisierung:</strong> <code>ucmSoftwareVersion</code> ermöglicht es Diagnose-Diensten und dem Fahrzeug-Update-Manager, die Version des UCM-Stacks selbst abzufragen und modellbasiert abzugleichen.</li>\n<li><strong>Ressourcenmanagement:</strong> <code>maxNumberOfParallelTransfers</code> begrenzt die parallele Ausführung von Transfer-Vorgängen zur Absicherung von Speicher- und Rechenressourcen.</li>\n<li><strong>Eindeutigkeit & Flottenarchitektur:</strong> Der <code>identifier</code> sichert die eindeutige Adressierbarkeit der Instanz.</li>\n</ul>"}, {"id": "FIG-1b967bfda8374898", "releases": ["R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong> Modellierung der verteilten UCM-Architektur (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Das Metamodell differenziert zwischen übergeordneter Orchestrierung (<code>UcmMasterModuleInstantiation</code>) und ausführenden lokalen Instanzen (<code>UcmSubordinateModuleInstantiation</code>) und etabliert konfigurierbare Wiederholungsstrategien (<code>UcmRetryStrategy</code>) zur Absicherung robuster Software-Update-Prozesse.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, Stereotyp <code>«AtpStructureElement»</code>)</em>:</li>\n<li>Basisklasse für alle Modulinstanziierungen der Adaptive Platform im Machine Manifest.</li>\n<li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>AdaptiveModuleInstantiation</code>)</em>:</li>\n<li>Kapselt plattformspezifische, betriebssystemunabhängige funktionale Cluster.</li>\n<li><strong><code>UcmModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:</li>\n<li>Gemeinsame Basisklasse für UCM-Instanzen.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ identifier: String [0..1]</code>: Optionale Kennung der UCM-Instanz im Fahrzeugnetzwerk.</li>\n<li><code>+ maxBlockSize: PositiveInteger [0..1]</code>: Maximale Blockgröße in Bytes für Paketdatenblöcke bei der Übertragung.</li>\n<li><code>+ version: StrongRevisionLabelString [0..1]</code>: Versionsbezeichnung der UCM-Implementierung.</li>\n<li><strong><code>UcmSubordinateModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert eine untergeordnete UCM-Instanz, die Software-Pakete auf einer Zielmaschine empfängt, verifiziert und ausführt.</li>\n<li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong></li>\n<li><code>+prepareRollback</code> [0..1]: Wiederholungsstrategie für die Rollback-Vorbereitungsphase.</li>\n<li><code>+prepareUpdate</code> [0..1]: Wiederholungsstrategie für die Update-Vorbereitungsphase.</li>\n<li><code>+verifyUpdate</code> [0..1]: Wiederholungsstrategie für die Verifikationsphase.</li>\n<li><strong><code>UcmMasterModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert die übergeordnete UCM-Master-Instanz zur Orchestrierung von Flotten- bzw. Fahrzeug-Updates.</li>\n<li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong></li>\n<li><code>+blockInconsistent</code> [0..1]: Strategie bei Inkonsistenz empfangener oder übertragener Datenblöcke.</li>\n<li><code>+serviceBusy</code> [0..1]: Strategie bei temporärer Nichtverfügbarkeit bzw. Überlastung eines UCM-Dienstes.</li>\n<li><code>+updateSessionRejected</code> [0..1]: Strategie bei Zurückweisung einer Update-Sitzung.</li>\n<li><strong><code>UcmRetryStrategy</code></strong> <em>(konkret, Stereotyp <code>«Identifiable»</code>)</em>:</li>\n<li>Kapselt Parameter für automatische Wiederholungsversuche bei Fehlern.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ maximumNumberOfRetries: PositiveInteger [0..1]</code>: Maximale Anzahl aufeinanderfolgender Wiederholungsversuche.</li>\n<li><code>+ retryIntervalTime: TimeValue [0..1]</code>: Zeitspanne zwischen zwei Wiederholungsversuchen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen vollständigen Sequenzablauf ab, definiert aber die Kontrollfluss-Parameter für die Fehlerbehandlung zur Laufzeit.</li>\n<li><strong>Laufzeit-Bezug & Retry-Verhalten:</strong></li>\n<li><strong>Subordinate-Zustandsübergänge:</strong> Schlagen Phasen wie <code>prepareUpdate</code>, <code>verifyUpdate</code> oder <code>prepareRollback</code> auf einer untergeordneten UCM-Instanz fehl, steuert die zugeordnete <code>UcmRetryStrategy</code> nach Wartezeit (<code>retryIntervalTime</code>) automatisierte erneute Versuche bis zum Limit <code>maximumNumberOfRetries</code>.</li>\n<li><strong>Master-Orchestrierung:</strong> Tritt beim Master ein Fehler auf (z. B. <code>serviceBusy</code>, <code>blockInconsistent</code> oder <code>updateSessionRejected</code>), bricht der Master den Gesamtprozess nicht unmittelbar ab, sondern initiiert programmierte Wiederholungen gemäß der konfigurierten Retry-Strategie.</li>\n<li><strong>Paketübertragung:</strong> <code>maxBlockSize</code> begrenzt die Payload-Größe bei iterativen Block-Transfers (<code>TransferData</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Erstellung & XML-Schema:</strong></li>\n<li><code>&lt;UCM-MODULE-INSTANTIATION&gt;</code> ist abstrakt; im Machine Manifest sind stattdessen konkrete Instanzen von <code>&lt;UCM-MASTER-MODULE-INSTANTIATION&gt;</code> oder <code>&lt;UCM-SUBORDINATE-MODULE-INSTANTIATION&gt;</code> anzulegen.</li>\n<li>Das Attribut <code>identifier</code> ist optional (<code>[0..1]</code>), <code>maxBlockSize</code> und <code>version</code> können optional auf Basisebene deklariert werden.</li>\n<li>Wiederholungsstrategien werden als eingebettete <code>&lt;UCM-RETRY-STRATEGY&gt;</code>-Elemente unter den spezifischen Rollenpfaden (z. B. <code>&lt;PREPARE-UPDATE&gt;</code>, <code>&lt;SERVICE-BUSY&gt;</code>) konfiguriert.</li>\n<li><strong>Stack- & Integrator-Relevanz:</strong></li>\n<li><strong>Fehlertoleranz:</strong> Integratoren müssen Timeouts und Retry-Zyklen aufeinander abstimmen, damit Retry-Schleifen von Subordinates nicht zu vorzeitigen Timeouts des Masters führen.</li>\n<li><strong>Netzwerkoptimierung:</strong> <code>maxBlockSize</code> muss an die MTU und Puffergrößen des zugrundeliegenden Transportprotokolls angepasst werden.</li>\n</ul>"}, {"id": "FIG-90c20195e857812e", "releases": ["R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong> Modellierung der verteilten UCM-Architektur (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Das Metamodell differenziert zwischen übergeordneter Orchestrierung (<code>UcmMasterModuleInstantiation</code>) und ausführenden lokalen Instanzen (<code>UcmSubordinateModuleInstantiation</code>) und etabliert konfigurierbare Wiederholungsstrategien (<code>UcmRetryStrategy</code>) zur Absicherung robuster Software-Update-Prozesse.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, Stereotyp <code>«AtpStructureElement»</code>)</em>:</li>\n<li>Basisklasse für alle Modulinstanziierungen der Adaptive Platform im Machine Manifest.</li>\n<li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>AdaptiveModuleInstantiation</code>)</em>:</li>\n<li>Kapselt plattformspezifische, betriebssystemunabhängige funktionale Cluster.</li>\n<li><strong><code>UcmModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:</li>\n<li>Gemeinsame Basisklasse für UCM-Instanzen.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ identifier: String [0..1]</code>: Optionale Kennung der UCM-Instanz im Fahrzeugnetzwerk.</li>\n<li><code>+ maxBlockSize: PositiveInteger [0..1]</code>: Maximale Blockgröße in Bytes für Paketdatenblöcke bei der Übertragung.</li>\n<li><code>+ version: StrongRevisionLabelString [0..1]</code>: Versionsbezeichnung der UCM-Implementierung.</li>\n<li><strong><code>UcmSubordinateModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert eine untergeordnete UCM-Instanz zur lokalen Paketverarbeitung und -aktivierung.</li>\n<li><strong>Attribut:</strong></li>\n<li><code>+ maxAvailablePersistencyStorageSpace: PositiveInteger [0..1]</code>: Maximal verfügbarer persistenter Speicherplatz (in Bytes), der für Software-Pakete und persistente Daten reserviert ist.</li>\n<li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong></li>\n<li><code>+prepareRollback</code> [0..1]: Wiederholungsstrategie für die Rollback-Vorbereitungsphase.</li>\n<li><code>+prepareUpdate</code> [0..1]: Wiederholungsstrategie für die Update-Vorbereitungsphase.</li>\n<li><code>+verifyUpdate</code> [0..1]: Wiederholungsstrategie für die Verifikationsphase.</li>\n<li><strong><code>UcmMasterModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert die übergeordnete UCM-Master-Instanz zur Orchestrierung von Flotten- bzw. Fahrzeug-Updates.</li>\n<li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong></li>\n<li><code>+blockInconsistent</code> [0..1]: Strategie bei Inkonsistenz empfangener oder übertragener Datenblöcke.</li>\n<li><code>+serviceBusy</code> [0..1]: Strategie bei temporärer Nichtverfügbarkeit bzw. Überlastung eines UCM-Dienstes.</li>\n<li><code>+updateSessionRejected</code> [0..1]: Strategie bei Zurückweisung einer Update-Sitzung.</li>\n<li><strong><code>UcmRetryStrategy</code></strong> <em>(konkret, Stereotyp <code>«Identifiable»</code>)</em>:</li>\n<li>Kapselt Parameter für automatische Wiederholungsversuche bei Fehlern.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ maximumNumberOfRetries: PositiveInteger [0..1]</code>: Maximale Anzahl aufeinanderfolgender Wiederholungsversuche.</li>\n<li><code>+ retryIntervalTime: TimeValue [0..1]</code>: Zeitspanne zwischen zwei Wiederholungsversuchen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen vollständigen Sequenzablauf ab, definiert aber die Kontrollfluss-Parameter für die Fehlerbehandlung zur Laufzeit.</li>\n<li><strong>Laufzeit-Bezug & Retry-Verhalten:</strong></li>\n<li><strong>Subordinate-Zustandsübergänge:</strong> Schlagen Phasen wie <code>prepareUpdate</code>, <code>verifyUpdate</code> oder <code>prepareRollback</code> auf einer untergeordneten UCM-Instanz fehl, steuert die zugeordnete <code>UcmRetryStrategy</code> nach Wartezeit (<code>retryIntervalTime</code>) automatisierte erneute Versuche bis zum Limit <code>maximumNumberOfRetries</code>.</li>\n<li><strong>Master-Orchestrierung:</strong> Tritt beim Master ein Fehler auf (z. B. <code>serviceBusy</code>, <code>blockInconsistent</code> oder <code>updateSessionRejected</code>), bricht der Master den Gesamtprozess nicht unmittelbar ab, sondern initiiert programmierte Wiederholungen gemäß der konfigurierten Retry-Strategie.</li>\n<li><strong>Paketübertragung:</strong> <code>maxBlockSize</code> begrenzt die Payload-Größe bei iterativen Block-Transfers (<code>TransferData</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Erstellung & XML-Schema:</strong></li>\n<li>Unter <code>&lt;UCM-SUBORDINATE-MODULE-INSTANTIATION&gt;</code> kann optional das Element <code>&lt;MAX-AVAILABLE-PERSISTENCY-STORAGE-SPACE&gt;</code> als ganzzahliger Wert konfiguriert werden.</li>\n<li>Die restliche XML-Struktur für Master, Subordinate und Retry-Strategien bleibt unverändert.</li>\n<li><strong>Stack- & Integrator-Relevanz:</strong></li>\n<li><strong>Speichervalidierung:</strong> Integratoren und Update-Tools können anhand von <code>maxAvailablePersistencyStorageSpace</code> bereits vor Beginn eines Transfers prüfen, ob der auf der Zielmaschine zugewiesene Speicherplatz für das auszurollende Software-Paket ausreicht, um Speicherüberläufe zur Laufzeit abzuwenden.</li>\n</ul>"}, {"id": "FIG-83cd2b631bb1246e", "releases": ["R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong> Modellierung der verteilten UCM-Architektur (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Das Metamodell differenziert zwischen übergeordneter Orchestrierung (<code>UcmMasterModuleInstantiation</code>) und ausführenden lokalen Instanzen (<code>UcmSubordinateModuleInstantiation</code>) und etabliert konfigurierbare Wiederholungsstrategien (<code>UcmRetryStrategy</code>) zur Absicherung robuster Software-Update-Prozesse.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, Stereotyp <code>«AtpStructureElement»</code>)</em>:</li>\n<li>Basisklasse für alle Modulinstanziierungen der Adaptive Platform im Machine Manifest.</li>\n<li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>AdaptiveModuleInstantiation</code>)</em>:</li>\n<li>Kapselt plattformspezifische, betriebssystemunabhängige funktionale Cluster.</li>\n<li><strong><code>UcmModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:</li>\n<li>Gemeinsame Basisklasse für UCM-Instanzen.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ identifier: String [0..1]</code>: Optionale Kennung der UCM-Instanz im Fahrzeugnetzwerk.</li>\n<li><code>+ maxBlockSize: PositiveInteger [0..1]</code>: Maximale Blockgröße in Bytes für Paketdatenblöcke bei der Übertragung.</li>\n<li><code>+ version: StrongRevisionLabelString [0..1]</code>: Versionsbezeichnung der UCM-Implementierung.</li>\n<li><strong><code>UcmSubordinateModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert eine untergeordnete UCM-Instanz zur lokalen Paketverarbeitung und -aktivierung.</li>\n<li><strong>Attribut:</strong></li>\n<li><code>+ maxAvailablePersistencyStorageSpace: PositiveInteger [0..1]</code>: Maximal verfügbarer persistenter Speicherplatz in Bytes.</li>\n<li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong></li>\n<li><code>+prepareRollback</code> [0..1]: Wiederholungsstrategie für die Rollback-Vorbereitungsphase.</li>\n<li><code>+prepareUpdate</code> [0..1]: Wiederholungsstrategie für die Update-Vorbereitungsphase.</li>\n<li><code>+verifyUpdate</code> [0..1]: Wiederholungsstrategie für die Verifikationsphase.</li>\n<li><strong><code>UcmMasterModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert die übergeordnete UCM-Master-Instanz zur Orchestrierung von Flotten- bzw. Fahrzeug-Updates.</li>\n<li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong></li>\n<li><code>+blockInconsistent</code> [0..1]: Strategie bei Inkonsistenz empfangener oder übertragener Datenblöcke.</li>\n<li><code>+serviceBusy</code> [0..1]: Strategie bei temporärer Nichtverfügbarkeit bzw. Überlastung eines UCM-Dienstes.</li>\n<li><code>+ucmNotAvailableOnTheNetwork</code> [0..1]: Wiederholungsstrategie bei netzwerkweiter Unerreichbarkeit einer untergeordneten UCM-Instanz.</li>\n<li><code>+updateSessionRejected</code> [0..1]: Strategie bei Zurückweisung einer Update-Sitzung.</li>\n<li><strong><code>UcmRetryStrategy</code></strong> <em>(konkret, Stereotyp <code>«Identifiable»</code>)</em>:</li>\n<li>Kapselt Parameter für automatische Wiederholungsversuche bei Fehlern.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ maximumNumberOfRetries: PositiveInteger [0..1]</code>: Maximale Anzahl aufeinanderfolgender Wiederholungsversuche.</li>\n<li><code>+ retryIntervalTime: TimeValue [0..1]</code>: Zeitspanne zwischen zwei Wiederholungsversuchen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen vollständigen Sequenzablauf ab, definiert aber die Kontrollfluss-Parameter für die Fehlerbehandlung zur Laufzeit.</li>\n<li><strong>Laufzeit-Bezug & Retry-Verhalten:</strong></li>\n<li><strong>Subordinate-Zustandsübergänge:</strong> Schlagen Phasen wie <code>prepareUpdate</code>, <code>verifyUpdate</code> oder <code>prepareRollback</code> auf einer untergeordneten UCM-Instanz fehl, steuert die zugeordnete <code>UcmRetryStrategy</code> nach Wartezeit (<code>retryIntervalTime</code>) automatisierte erneute Versuche bis zum Limit <code>maximumNumberOfRetries</code>.</li>\n<li><strong>Master-Orchestrierung & Netzwerkausfälle:</strong> Kann der Master eine untergeordnete UCM-Instanz im Netzwerk temporär nicht erreichen (z. B. Verbindungsunterbrechung oder verzögerter Start), greift die Wiederholungsstrategie <code>ucmNotAvailableOnTheNetwork</code>. Erst nach Erschöpfen der konfigurierten Versuche bricht die Kampagne ab.</li>\n<li><strong>Weitere Master-Fehlerstrategien:</strong> Bei <code>serviceBusy</code>, <code>blockInconsistent</code> oder <code>updateSessionRejected</code> steuern die jeweiligen Retry-Strategien das automatisierte Wiederaufsetzen des Update-Dialogs.</li>\n<li><strong>Paketübertragung:</strong> <code>maxBlockSize</code> begrenzt die Payload-Größe bei iterativen Block-Transfers (<code>TransferData</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Erstellung & XML-Schema:</strong></li>\n<li>Unter <code>&lt;UCM-MASTER-MODULE-INSTANTIATION&gt;</code> kann nun zusätzlich die Rolle <code>&lt;UCM-NOT-AVAILABLE-ON-THE-NETWORK&gt;</code> mit einer eingebetteten <code>&lt;UCM-RETRY-STRATEGY&gt;</code> (mit <code>&lt;MAXIMUM-NUMBER-OF-RETRIES&gt;</code> und <code>&lt;RETRY-INTERVAL-TIME&gt;</code>) konfiguriert werden.</li>\n<li><strong>Stack- & Integrator-Relevanz:</strong></li>\n<li><strong>Netzwerk-Robustheit:</strong> Integratoren können über <code>ucmNotAvailableOnTheNetwork</code> gezielt transiente Netzwerkstörungen oder Boot-Verzögerungen entfernter Steuergeräte abfangen, ohne dass Kampagnen sofort als fehlgeschlagen markiert werden.</li>\n</ul>"}, {"id": "FIG-edc4d3e2544830f8", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Klassendiagramm / Metamodell-Ausschnitt (M2-Ebene) der <em>AUTOSAR Adaptive Platform Manifest Specification</em> (<code>AUTOSAR_TPS_ManifestSpecification</code>).</li>\n<li><strong>Technischer Zweck & funktionale Einordnung:</strong> Modellierung der verteilten UCM-Architektur (<em>Update and Configuration Management</em>) im <em>Machine Manifest</em>. Das Metamodell differenziert zwischen übergeordneter Orchestrierung (<code>UcmMasterModuleInstantiation</code>) und ausführenden lokalen Instanzen (<code>UcmSubordinateModuleInstantiation</code>) und etabliert konfigurierbare Wiederholungsstrategien (<code>UcmRetryStrategy</code>) zur Absicherung robuster Software-Update-Prozesse.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong><code>AdaptiveModuleInstantiation</code></strong> <em>(abstrakt, Stereotyp <code>«AtpStructureElement»</code>)</em>:</li>\n<li>Basisklasse für alle Modulinstanziierungen der Adaptive Platform im Machine Manifest.</li>\n<li><strong><code>NonOsModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>AdaptiveModuleInstantiation</code>)</em>:</li>\n<li>Kapselt plattformspezifische, betriebssystemunabhängige funktionale Cluster.</li>\n<li><strong><code>UcmModuleInstantiation</code></strong> <em>(abstrakt, spezialisiert <code>NonOsModuleInstantiation</code>)</em>:</li>\n<li>Gemeinsame Basisklasse für UCM-Instanzen.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ identifier: String [0..1]</code>: Optionale Kennung der UCM-Instanz im Fahrzeugnetzwerk.</li>\n<li><code>+ maxBlockSize: PositiveInteger [0..1]</code>: Maximale Blockgröße in Bytes für Paketdatenblöcke bei der Übertragung.</li>\n<li><code>+ version: StrongRevisionLabelString [0..1]</code>: Versionsbezeichnung der UCM-Implementierung.</li>\n<li><strong><code>UcmSubordinateModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert eine untergeordnete UCM-Instanz zur lokalen Paketverarbeitung und -aktivierung.</li>\n<li><strong>Attribut:</strong></li>\n<li><code>+ maxAvailablePersistencyStorageSpace: PositiveInteger [0..1]</code>: Maximal verfügbarer persistenter Speicherplatz in Bytes.</li>\n<li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong></li>\n<li><code>+prepareRollback</code> [0..1]: Wiederholungsstrategie für die Rollback-Vorbereitungsphase.</li>\n<li><code>+prepareUpdate</code> [0..1]: Wiederholungsstrategie für die Update-Vorbereitungsphase.</li>\n<li><code>+verifyUpdate</code> [0..1]: Wiederholungsstrategie für die Verifikationsphase.</li>\n<li><strong><code>UcmMasterModuleInstantiation</code></strong> <em>(konkret, spezialisiert <code>UcmModuleInstantiation</code>)</em>:</li>\n<li>Repräsentiert die übergeordnete UCM-Master-Instanz zur Orchestrierung von Flotten- bzw. Fahrzeug-Updates.</li>\n<li><strong>Kompositionen zu <code>UcmRetryStrategy</code>:</strong></li>\n<li><code>+blockInconsistent</code> [0..1]: Strategie bei Inkonsistenz empfangener oder übertragener Datenblöcke.</li>\n<li><code>+serviceBusy</code> [0..1]: Strategie bei temporärer Nichtverfügbarkeit bzw. Überlastung eines UCM-Dienstes.</li>\n<li><code>+ucmNotAvailableOnTheNetwork</code> [0..1]: Wiederholungsstrategie bei netzwerkweiter Unerreichbarkeit einer untergeordneten UCM-Instanz.</li>\n<li><code>+updateSessionRejected</code> [0..1]: Strategie bei Zurückweisung einer Update-Sitzung.</li>\n<li><strong><code>UcmRetryStrategy</code></strong> <em>(konkret, Stereotyp <code>«Identifiable»</code>)</em>:</li>\n<li>Kapselt Parameter für automatische Wiederholungsversuche bei Fehlern.</li>\n<li><strong>Attribute:</strong></li>\n<li><code>+ maximumNumberOfRetries: PositiveInteger [0..1]</code>: Maximale Anzahl aufeinanderfolgender Wiederholungsversuche.</li>\n<li><code>+ retryIntervalTime: TimeValue [0..1]</code>: Zeitspanne zwischen zwei Wiederholungsversuchen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ul class=\"fig-list\">\n<li>Als statisches Metamodell-Klassendiagramm bildet die Darstellung keinen vollständigen Sequenzablauf ab, definiert aber die Kontrollfluss-Parameter für die Fehlerbehandlung zur Laufzeit.</li>\n<li><strong>Laufzeit-Bezug & Retry-Verhalten:</strong></li>\n<li><strong>Subordinate-Zustandsübergänge:</strong> Schlagen Phasen wie <code>prepareUpdate</code>, <code>verifyUpdate</code> oder <code>prepareRollback</code> auf einer untergeordneten UCM-Instanz fehl, steuert die zugeordnete <code>UcmRetryStrategy</code> nach Wartezeit (<code>retryIntervalTime</code>) automatisierte erneute Versuche bis zum Limit <code>maximumNumberOfRetries</code>.</li>\n<li><strong>Master-Orchestrierung & Netzwerkausfälle:</strong> Kann der Master eine untergeordnete UCM-Instanz im Netzwerk temporär nicht erreichen (z. B. Verbindungsunterbrechung oder verzögerter Start), greift die Wiederholungsstrategie <code>ucmNotAvailableOnTheNetwork</code>. Erst nach Erschöpfen der konfigurierten Versuche bricht die Kampagne ab.</li>\n<li><strong>Weitere Master-Fehlerstrategien:</strong> Bei <code>serviceBusy</code>, <code>blockInconsistent</code> oder <code>updateSessionRejected</code> steuern die jeweiligen Retry-Strategien das automatisierte Wiederaufsetzen des Update-Dialogs.</li>\n<li><strong>Paketübertragung:</strong> <code>maxBlockSize</code> begrenzt die Payload-Größe bei iterativen Block-Transfers (<code>TransferData</code>).</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>Manifest-Erstellung & XML-Schema:</strong></li>\n<li>Unter <code>&lt;UCM-MASTER-MODULE-INSTANTIATION&gt;</code> kann nun zusätzlich die Rolle <code>&lt;UCM-NOT-AVAILABLE-ON-THE-NETWORK&gt;</code> mit einer eingebetteten <code>&lt;UCM-RETRY-STRATEGY&gt;</code> (mit <code>&lt;MAXIMUM-NUMBER-OF-RETRIES&gt;</code> und <code>&lt;RETRY-INTERVAL-TIME&gt;</code>) konfiguriert werden.</li>\n<li><strong>Stack- & Integrator-Relevanz:</strong></li>\n<li><strong>Netzwerk-Robustheit:</strong> Integratoren können über <code>ucmNotAvailableOnTheNetwork</code> gezielt transiente Netzwerkstörungen oder Boot-Verzögerungen entfernter Steuergeräte abfangen, ohne dass Kampagnen sofort als fehlgeschlagen markiert werden.</li>\n</ul>"}], "trans": [{"from": "FIG-d84cc1eca92e394c", "to": "FIG-f5e1a0b0f072564c", "fr": "R19-03", "tr": "R19-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>UcmModuleInstantiation</code>: Typ des Attributs <code>identifier</code> von <code>PositiveInteger</code> zu <code>String</code> geändert.</li>\n</ul>"}, {"from": "FIG-f5e1a0b0f072564c", "to": "FIG-d1e4d1f49b74913e", "fr": "R19-11", "tr": "R20-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>UcmModuleInstantiation</code>: Attribut <code>maxNumberOfParallelTransfers: PositiveInteger [0..1]</code> neu hinzugefügt.</li>\n</ul>"}, {"from": "FIG-d1e4d1f49b74913e", "to": "FIG-2b8832dbea56b0bb", "fr": "R20-11", "tr": "R21-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>UcmModuleInstantiation</code>: Attribut <code>ucmSoftwareVersion: StrongRevisionLabelString [0..1]</code> neu hinzugefügt.</li>\n</ul>"}, {"from": "FIG-2b8832dbea56b0bb", "to": "FIG-1b967bfda8374898", "fr": "R21-11", "tr": "R22-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>AdaptiveModuleInstantiation</code>: Stereotyp <code>«AtpStructureElement»</code> ergänzt.</li>\n<li><code>UcmModuleInstantiation</code>: Metaklasse als abstrakt deklariert (kursiver Name); Kardinalität von <code>identifier</code> von <code>[1]</code> auf <code>[0..1]</code> gelockert; Attribut <code>maxNumberOfParallelTransfers</code> entfernt; Attribut <code>maxBlockSize: PositiveInteger [0..1]</code> neu hinzugefügt; Attribut <code>ucmSoftwareVersion</code> zu <code>version: StrongRevisionLabelString [0..1]</code> umbenannt.</li>\n<li><code>UcmMasterModuleInstantiation</code>: Neue Metaklasse eingeführt (spezialisiert <code>UcmModuleInstantiation</code>).</li>\n<li><code>UcmSubordinateModuleInstantiation</code>: Neue Metaklasse eingeführt (spezialisiert <code>UcmModuleInstantiation</code>).</li>\n<li><code>UcmRetryStrategy</code>: Neue Metaklasse eingeführt (Stereotyp <code>«Identifiable»</code>, Attribute <code>maximumNumberOfRetries: PositiveInteger [0..1]</code> und <code>retryIntervalTime: TimeValue [0..1]</code>).</li>\n<li>Kompositionen von <code>UcmSubordinateModuleInstantiation</code> zu <code>UcmRetryStrategy</code> neu eingeführt: <code>prepareRollback</code> [0..1], <code>prepareUpdate</code> [0..1], <code>verifyUpdate</code> [0..1].</li>\n<li>Kompositionen von <code>UcmMasterModuleInstantiation</code> zu <code>UcmRetryStrategy</code> neu eingeführt: <code>blockInconsistent</code> [0..1], <code>serviceBusy</code> [0..1], <code>updateSessionRejected</code> [0..1].</li>\n</ul>"}, {"from": "FIG-1b967bfda8374898", "to": "FIG-90c20195e857812e", "fr": "R22-11", "tr": "R23-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>UcmSubordinateModuleInstantiation</code>: Attribut <code>maxAvailablePersistencyStorageSpace: PositiveInteger [0..1]</code> neu hinzugefügt.</li>\n</ul>"}, {"from": "FIG-90c20195e857812e", "to": "FIG-83cd2b631bb1246e", "fr": "R23-11", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li><code>UcmMasterModuleInstantiation</code>: Neue Kompositions-Rolle <code>ucmNotAvailableOnTheNetwork</code> [0..1] zu <code>UcmRetryStrategy</code> hinzugefügt.</li>\n</ul>"}, {"from": "FIG-83cd2b631bb1246e", "to": "FIG-edc4d3e2544830f8", "fr": "R24-11", "tr": "R25-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
